def max_value_on_paths(N: int, grid_values: List[Tuple[int, int, int]]) -> int:
    # Initialize the dp table with 0 for all positions
    dp = [[0] * N for _ in range(N)]

    # Iterate through the grid_values and update the dp table
    for x, y, value in grid_values:
        if x == 0 and y == 0:
            dp[x][y] = value
        elif x > 0 and y == 0:
            dp[x][y] = max(value, dp[x-1][y])
        elif x == 0 and y > 0:
            dp[x][y] = max(value, dp[x][y-1])
        else:
            dp[x][y] = max(value, dp[x-1][y], dp[x][y-1])

    # Return the maximum value in the bottom right corner of the dp table
    return dp[N-1][N-1]
