    for i in range(K):
        for j in range(L):
            classroom[i + 1][j + 1] = 1

    # Count the number of chatting pairs that can be separated by an aisle
    count = 0
    for pair in chatting_pairs:
        x1, y1, x2, y2 = pair
        if classroom[x1][y1] != classroom[x2][y2]:
            count += 1

    # Select the most effective aisle positions
    optimal_rows = []
    optimal_cols = []
